/* ===== PS01-NOTION 结构观感（v3.42.0）===== */
/* 页签 chip 化：全胶囊 + 1px 描边 + 浅底，激活 = 深墨底白字 */
QMainWindow #tabstrip QTabBar::tab:!selected {
  background: {bg_soft};
  color: {tab_text};
  border: 1px solid {border};
  border-radius: 15px;
  padding: 4px 14px;
  margin: 2px 4px 3px 0;
}
QMainWindow #tabstrip QTabBar::tab:hover:!selected {
  background: {hover_bg};
  color: {hover_text};
  border-color: {input_border};
}
QMainWindow #tabstrip QTabBar::tab:selected {
  background: {tab_sel_bg};
  color: {tab_sel_text};
  border-color: {input_border};
  border-top: 1px solid {input_border};
  font-weight: 500;
}
/* 菜单：弱化文字 + hover 暖灰；高亮项用反色保证可读 */
QMenu {
  border-radius: 6px;
}
QMenu::item:selected {
  background: {menu_hover_bg};
  color: {menu_sel_text};
}
QMenuBar::item {
  border-radius: 5px;
}
/* 激活态统一深墨底白字（#vsz = 右端视图状态区）*/
#vsz QToolButton:checked {
  background: {accent};
  color: {menu_sel_text};
}
/* 状态栏：无底色 + 细顶线 */
QStatusBar {
  background: {bg};
  min-height: 28px;
}
